// Scope matrix: consumer × tool → allow | gate | deny (plain JS)
const SCOPES = {
  "support-assistant": { "lookup-order": "allow", "search-orders": "allow", "issue-refund": "deny" },
  "finance-agent": { "lookup-order": "allow", "issue-refund": "gate" },
  "analytics-job": { "order-stats": "allow", "issue-refund": "deny", "lookup-order": "deny" },
};
function authorize(consumer, tool) {
  const rule = (SCOPES[consumer] || {})[tool];
  return rule || "deny"; // default-deny: unlisted pairs refuse loudly
}
// Default-deny closes the 'new tool, forgotten scopes' hole by construction.

// Gated execution: authorize → elicit → execute-or-skip (plain JS pattern)
async function gatedCall(consumer, tool, args, ctx) {
  const rule = authorize(consumer, tool.name);
  if (rule === "deny") return { ok: false, error: "forbidden", audit: logAttempt(consumer, tool, args, "denied") };
  if (rule === "gate") {
    const verdict = await ctx.elicit({ action: tool.name, args }); // approve|edit|skip
    ctx.audit({ consumer, tool: tool.name, args, verdict });
    if (verdict.decision !== "approve") return { ok: false, error: "not-approved:" + verdict.decision };
    args = verdict.editedArgs || args; // edits validated like fresh args
  }
  return tool.run(args);
}
// Every path audited: allowed, denied, approved, edited, skipped.

